   public class RegistrationDetector extends Detector implements XmlScanner, SourceCodeScanner {
       private Set<String> registeredComponents = new HashSet<>();
       private String manifestPackage = "";

       public static final Issue ISSUE = Issue.create(
           "Registered",
           "Class is not registered in the manifest",
           "Activities, services and content providers should be registered in the `AndroidManifest.xml` file using `<activity>`, `<service>` and `<provider>` tags.\n\nIf your activity is simply a parent class intended to be subclassed by other \"real\" activities, make it an abstract class.",
           Category.CORRECTNESS,
           6,
           Severity.ERROR,
           new Implementation(RegistrationDetector.class, Scope.JAVA_AND_RESOURCE_FILES)
       );

       @Override
       public void beforeCheckProject(Context context) {
           registeredComponents.clear();
           manifestPackage = context.getProject().getPackage();
           if (manifestPackage == null) manifestPackage = "";
       }

       @Override
       public Collection<String> getApplicableElements() {
           return Arrays.asList("activity", "service", "provider");
       }

       @Override
       public void visitElement(XmlContext context, Element element) {
           String name = element.getAttributeNS(SdkConstants.ANDROID_URI, "name");
           if (name != null && !name.isEmpty()) {
               registeredComponents.add(resolveClassName(name, manifestPackage));
           }
       }

       @Override
       public List<String> applicableSuperClasses() {
           return Arrays.asList(
               "android.app.Activity",
               "android.app.Service",
               "android.content.ContentProvider"
           );
       }

       @Override
       public void visitClass(JavaContext context, UClass node) {
           if (node.hasModifier(UastModifier.ABSTRACT)) {
               return;
           }
           String qualifiedName = node.getQualifiedName();
           if (qualifiedName == null) return;

           if (!registeredComponents.contains(qualifiedName)) {
               context.report(ISSUE, node, context.getLocation(node),
                   "Class is not registered in the manifest");
           }
       }

       private static String resolveClassName(String name, String pkg) {
           if (name.startsWith(".")) {
               return pkg + name;
           } else if (name.indexOf('.') == -1) {
               return pkg + "." + name;
           }
           return name;
       }
   }
   ```

