       @Override
       public void beforeCheckProject(Context context) {
           registeredComponents.clear();
           String pkg = context.getProject().getPackage();
           manifestPackage = pkg != null ? pkg : "";
       }

       @Override
       public boolean appliesTo(Context context, File file) {
